export const getLanguage=()=>language;
export function switcher(){return `<div class="language-switcher" role="group" aria-label="Language / Bahasa"><button type="button" data-language="en" aria-label="English" aria-pressed="${language==='en'}" title="English">EN</button><span aria-hidden="true">/</span><button type="button" data-language="id" aria-label="Bahasa Indonesia" aria-pressed="${language==='id'}" title="Bahasa Indonesia">IN</button></div>`;}

// Translate in place to preserve draft values, focus, caret, expanded help,
